package com.zickat.shopifymcpserver.shared_kernel

import io.kotest.matchers.shouldBe
import kotlinx.serialization.json.Json
import org.junit.jupiter.api.Test

/**
 * Proves, for each `LOT5-01` read-only cassette (the five read tools of `products.ts` —
 * `search_products`, `get_raw_content`, `get_enriched_content`, `list_to_review`,
 * `list_orphan_products`), that the harness built in `LOT1-02` loads it and replays it
 * faithfully — not yet against a native Kotlin port (none exists for these tools yet), same
 * scope as `Lot4ReadCassetteReplayTest`.
 *
 * Every expected response body is a literal copied from the cassette at recording time, kept
 * separate from what the test reads out of the cassette to build the request and to seed the
 * mock server — comparing a cassette against itself would pass even if the cassette were
 * corrupted.
 *
 * Several `search_products`/`list_orphan_products` calls share one literal: status filtering
 * happens client-side in `products.ts` (search index lag documented in its source), so the
 * underlying GraphQL request/response is byte-identical across `status_filter` values on the
 * same store, and the list_orphan_products products-scan query selects the same fields as
 * search_products — reusing one constant is the literal truth, not a shortcut.
 */
class Lot5ReadCassetteReplayTest {

    private val json = Json { ignoreUnknownKeys = true }

    private fun replayAndAssert(resourcePath: String, expectedResponseBodies: List<String>) {
        // given
        val cassette = Cassette.fromClasspathResource(resourcePath)
        val server = CassetteMockWebServer.forShopifyAdminGraphQL(cassette)
        require(cassette.calls.size == expectedResponseBodies.size) {
            "cassette $resourcePath has ${cassette.calls.size} call(s), but ${expectedResponseBodies.size} expected response(s) were given"
        }

        // when / then
        cassette.calls.forEachIndexed { index, call ->
            val request = json.decodeFromJsonElement(ShopifyAdminGraphQLRequest.serializer(), call.request)

            val response = CassetteMockWebServer.postGraphQL(server, request.query, request.variables)

            response.code shouldBe 200
            json.parseToJsonElement(response.body!!.string()) shouldBe
                json.parseToJsonElement("""{"data":${expectedResponseBodies[index]}}""")
        }
        server.shutdown()
    }

